def re_arrange(arr, n):
    # Separate positive and negative numbers
    pos = []
    neg = []
    for num in arr:
        if num >= 0:
            pos.append(num)
        else:
            neg.append(num)

    # Re-arrange the array
    result = []
    for i in range(min(len(pos), len(neg))):
        result.append(neg[i])
        result.append(pos[i])

    # Append remaining numbers
    if len(pos) > len(neg):
        result.extend(pos[len(neg):])
    else:
        result.extend(neg[len(pos):])

    return result

def num_comm_div(a, b):
    divisors = set()
    for i in range(1, min(a, b) + 1):
        if a % i == 0 and b % i == 0:
            divisors.add(i)
    return len(divisors) if divisors else 0
